/**
 * wAIbi-sabi Zero-API Radar Ingestion Bridge
 * 
 * Synchronizes trending topics and ideas generated by Gemini Spark in Google Sheets
 * directly into the Notion Pipeline Radar database (511e41a3-c1cd-47e0-8fa2-d319feef0ced).
 * 
 * Operates with ZERO paid API keys:
 * 1. Reads CSV export from Google Sheets 'Radar' tab.
 * 2. Deduplicates against existing Notion Radar rows by title.
 * 3. Appends new rows to Notion using NOTION_TOKEN.
 * 
 * Usage:
 *   node site/scripts/sync-radar.mjs [--commit]
 */

import { api, PIPELINE_DS, queryAll } from './lib/notion.mjs';
import { SHEET } from '../harness/registry.mjs';

const DEFAULT_SHEET_ID = SHEET.id;
const sheetId = process.env.GOOGLE_SHEET_ID || DEFAULT_SHEET_ID;
const commit = process.argv.includes('--commit');

// Parse CSV with RFC 4180 support
function parseCSV(text) {
  const lines = [];
  let row = [];
  let inQuotes = false;
  let field = '';

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    const next = text[i + 1];

    if (c === '"') {
      if (inQuotes && next === '"') {
        field += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (c === ',' && !inQuotes) {
      row.push(field);
      field = '';
    } else if ((c === '\r' || c === '\n') && !inQuotes) {
      if (c === '\r' && next === '\n') i++;
      row.push(field);
      field = '';
      if (row.some((cell) => cell.trim().length > 0)) lines.push(row);
      row = [];
    } else {
      field += c;
    }
  }
  if (field || row.length) {
    row.push(field);
    if (row.some((cell) => cell.trim().length > 0)) lines.push(row);
  }
  return lines;
}

console.log('──────────────────────────────────────────────────────');
console.log('wAIbi-sabi Zero-API Radar Sync (Google Sheets → Notion)');
console.log('──────────────────────────────────────────────────────');

const url = `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:csv&sheet=Radar`;
console.log(`Fetching Radar tab: ${url}`);

let csvText = '';
try {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  csvText = await res.text();
} catch (err) {
  console.warn(`Could not fetch Radar tab from Google Sheets: ${err.message}`);
  process.exit(0);
}

const rows = parseCSV(csvText);
if (rows.length <= 1) {
  console.log('No rows found in Radar tab. (Ensure tab "Radar" exists with header row).');
  process.exit(0);
}

const headers = rows[0].map((h) => h.trim().toLowerCase());
// Expected columns: Date, Track, Title, Reader Question, Pitch, Keywords, Optional: SeoBrief/DocUrl
const idx = {
  date: headers.indexOf('date'),
  track: headers.indexOf('track'),
  title: headers.findIndex((h) => h.includes('title') || h.includes('name')),
  question: headers.findIndex((h) => h.includes('question')),
  pitch: headers.indexOf('pitch'),
  keywords: headers.findIndex((h) => h.includes('keyword')),
  brief: headers.findIndex((h) => h.includes('brief') || h.includes('seo') || h.includes('doc') || h.includes('url') || h.includes('content') || h.includes('body')),
};

if (idx.title === -1 || idx.pitch === -1) {
  console.log('Tab does not appear to be a Radar table (missing Title or Pitch headers).');
  console.log('Headers found:', headers.join(', '));
  process.exit(0);
}

// Convert markdown text to Notion blocks
function markdownToBlocks(pitch, briefText) {
  const blocks = [];

  // Opening callout with the 100-word Pitch
  if (pitch) {
    blocks.push({
      object: 'block',
      type: 'callout',
      callout: {
        rich_text: [{ type: 'text', text: { content: `**Pitch:** ${pitch}`.slice(0, 2000) } }],
        icon: { emoji: '🔍' },
      },
    });
  }

  if (!briefText) return blocks;

  const lines = briefText.split('\n');
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];
    const trimmed = line.trim();

    if (!trimmed) {
      i++;
      continue;
    }

    // Markdown Table parsing
    if (trimmed.startsWith('|') && trimmed.endsWith('|')) {
      const tableLines = [];
      while (i < lines.length && lines[i].trim().startsWith('|') && lines[i].trim().endsWith('|')) {
        const rowText = lines[i].trim();
        // Skip markdown separator row |---|---|
        if (!/^\|(?:\s*:?-+:?\s*\|)+$/.test(rowText)) {
          tableLines.push(rowText);
        }
        i++;
      }
      if (tableLines.length > 0) {
        const parsedRows = tableLines.map((rowStr) =>
          rowStr
            .slice(1, -1)
            .split('|')
            .map((cell) => cell.trim())
        );
        const colWidth = Math.max(...parsedRows.map((r) => r.length));
        const tableBlock = {
          object: 'block',
          type: 'table',
          table: {
            table_width: colWidth,
            has_column_header: true,
            has_row_header: false,
            children: parsedRows.map((rowCells) => {
              const padded = [...rowCells];
              while (padded.length < colWidth) padded.push('');
              return {
                type: 'table_row',
                table_row: {
                  cells: padded.map((cellText) => [
                    { type: 'text', text: { content: cellText.slice(0, 1000) } },
                  ]),
                },
              };
            }),
          },
        };
        blocks.push(tableBlock);
      }
      continue;
    }

    // Headings
    if (trimmed.startsWith('### ')) {
      blocks.push({
        object: 'block',
        type: 'heading_3',
        heading_3: { rich_text: [{ type: 'text', text: { content: trimmed.slice(4).slice(0, 2000) } }] },
      });
      i++;
      continue;
    }
    if (trimmed.startsWith('## ')) {
      blocks.push({
        object: 'block',
        type: 'heading_2',
        heading_2: { rich_text: [{ type: 'text', text: { content: trimmed.slice(3).slice(0, 2000) } }] },
      });
      i++;
      continue;
    }
    if (trimmed.startsWith('# ')) {
      blocks.push({
        object: 'block',
        type: 'heading_1',
        heading_1: { rich_text: [{ type: 'text', text: { content: trimmed.slice(2).slice(0, 2000) } }] },
      });
      i++;
      continue;
    }

    // Bullet lists
    if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
      blocks.push({
        object: 'block',
        type: 'bulleted_list_item',
        bulleted_list_item: { rich_text: [{ type: 'text', text: { content: trimmed.slice(2).slice(0, 2000) } }] },
      });
      i++;
      continue;
    }

    // Numbered lists
    if (/^\d+\.\s+/.test(trimmed)) {
      const match = trimmed.match(/^\d+\.\s+(.+)$/);
      blocks.push({
        object: 'block',
        type: 'numbered_list_item',
        numbered_list_item: { rich_text: [{ type: 'text', text: { content: match[1].slice(0, 2000) } }] },
      });
      i++;
      continue;
    }

    // Quotes
    if (trimmed.startsWith('> ')) {
      blocks.push({
        object: 'block',
        type: 'quote',
        quote: { rich_text: [{ type: 'text', text: { content: trimmed.slice(2).slice(0, 2000) } }] },
      });
      i++;
      continue;
    }

    // Dividers
    if (trimmed === '---' || trimmed === '***') {
      blocks.push({ object: 'block', type: 'divider', divider: {} });
      i++;
      continue;
    }

    // Standard paragraph
    blocks.push({
      object: 'block',
      type: 'paragraph',
      paragraph: { rich_text: [{ type: 'text', text: { content: trimmed.slice(0, 2000) } }] },
    });
    i++;
  }

  return blocks;
}

// Fetch existing Notion Radar titles to prevent duplicates
console.log('Fetching existing Notion Radar ideas...');
const existingNotionRows = await queryAll(PIPELINE_DS);
const existingTitles = new Set(
  existingNotionRows.map((r) =>
    (r.properties.Name?.title?.[0]?.plain_text || '').trim().toLowerCase()
  )
);

const newIdeas = [];

for (let i = 1; i < rows.length; i++) {
  const r = rows[i];
  const title = (r[idx.title] ?? '').trim();
  if (!title) continue;

  const titleLower = title.toLowerCase();
  const truncatedLower = title.slice(0, 70).toLowerCase();
  if (existingTitles.has(titleLower) || existingTitles.has(truncatedLower)) {
    continue; // Already in Notion
  }

  const track = (r[idx.track] ?? 'Technical').trim() || 'Technical';
  const question = (r[idx.question] ?? '').trim();
  const pitch = (r[idx.pitch] ?? '').trim();
  const keywords = (r[idx.keywords] ?? '').trim();
  const briefOrUrl = idx.brief !== -1 ? (r[idx.brief] ?? '').trim() : '';

  newIdeas.push({ title, track, question, pitch, keywords, briefOrUrl });
}

console.log(`Found ${newIdeas.length} fresh radar idea(s) in Google Sheets.`);

if (newIdeas.length === 0) {
  console.log('All ideas in Google Sheet are already filed in Notion Radar.');
  process.exit(0);
}

for (const idea of newIdeas) {
  console.log(`\n• [${idea.track}] "${idea.title}" (${idea.title.length}/70 chars)`);
  if (idea.question) console.log(`  Question: "${idea.question}" (${idea.question.length}/120 chars)`);
  if (idea.briefOrUrl) console.log(`  SEO Brief: Present (${idea.briefOrUrl.length} chars / URL)`);

  if (!commit) {
    console.log('  [DRY RUN] Would file to Notion with full SEO brief. Pass --commit to push.');
    continue;
  }

  // Resolve SEO Brief content (from Google Doc link or direct markdown)
  let briefMarkdown = idea.briefOrUrl;
  if (briefMarkdown && (briefMarkdown.startsWith('http://') || briefMarkdown.startsWith('https://'))) {
    const docIdMatch = briefMarkdown.match(/\/d\/([a-zA-Z0-9_-]+)/);
    if (docIdMatch) {
      const docId = docIdMatch[1];
      const exportUrl = `https://docs.google.com/document/d/${docId}/export?format=txt`;
      console.log(`  Fetching Google Doc SEO brief: ${exportUrl}`);
      try {
        const docRes = await fetch(exportUrl);
        if (docRes.ok) {
          briefMarkdown = await docRes.text();
          console.log(`  ✓ Retrieved ${briefMarkdown.length} chars from Google Doc.`);
        }
      } catch (err) {
        console.warn(`  ✗ Could not fetch Google Doc brief: ${err.message}`);
      }
    }
  }

  const props = {
    Name: { title: [{ type: 'text', text: { content: idea.title.slice(0, 70) } }] },
    Track: { select: { name: idea.track } },
    Pitch: { rich_text: [{ type: 'text', text: { content: idea.pitch.slice(0, 2000) } }] },
    Status: { select: { name: 'Radar Idea' } },
  };
  if (idea.question) {
    props['Reader Question'] = { rich_text: [{ type: 'text', text: { content: idea.question.slice(0, 120) } }] };
  }
  if (idea.keywords) {
    props['SEO Keywords'] = { rich_text: [{ type: 'text', text: { content: idea.keywords.slice(0, 2000) } }] };
  }

  const blocks = markdownToBlocks(idea.pitch, briefMarkdown);
  const firstBatch = blocks.slice(0, 100);
  const remaining = blocks.slice(100);

  const page = await api('/pages', {
    method: 'POST',
    body: {
      parent: { data_source_id: PIPELINE_DS },
      properties: props,
      icon: { type: 'emoji', emoji: '🔍' },
      children: firstBatch,
    },
  });

  while (remaining.length > 0) {
    const chunk = remaining.splice(0, 100);
    await api(`/blocks/${page.id}/children`, {
      method: 'PATCH',
      body: { children: chunk },
    });
  }

  console.log(`  ✓ Filed to Notion Radar with full SEO Brief: ${page.id}`);
}

console.log('\nSync sweep finished.');
